script:
$ErrorActionPreference = 'Stop'
$root = 'C:/3EN-Agent'
$stateFile = "$root/3en-agent.state.json"
$controller = "$root/queue-controller-v3.ps1"
$newLog = "$root/queue-controller-v3.log"

Write-Host '=== READ / EVIDENCE ==='
$state = Get-Content -LiteralPath $stateFile -Raw | ConvertFrom-Json
Write-Host ('STATE_ID=' + $state.lastExecutedId)
Write-Host ('STATE_STATUS=' + $state.lastTerminalStatus)
if ($state.lastExecutedId -ne '2026-09-09-019a' -or $state.lastTerminalStatus -ne 'SUCCESS') {
    throw 'Expected HOLD 019a SUCCESS before queue repair.'
}

foreach ($name in @('queue-controller.log','queue-controller-v2.log')) {
    $p = "$root/$name"
    Write-Host ('--- ' + $name + ' ---')
    if (Test-Path -LiteralPath $p) {
        Get-Content -LiteralPath $p -Tail 120 | ForEach-Object { Write-Host $_ }
    } else {
        Write-Host 'MISSING'
    }
}

if ([string]::IsNullOrWhiteSpace($env:THREEEN_GH_TOKEN)) {
    throw 'THREEEN_GH_TOKEN missing in runner environment.'
}
Write-Host 'QUEUE_PAT_PRESENT=TRUE'

Write-Host '=== CONCLUSION ==='
Write-Host '041_042_LOOP_CAUSE=INVALID_TASK_JSON_NOT_RUNNER_TERMINALIZATION'
Write-Host 'QUEUE_REPAIR_REQUIRED=TRUE'

Write-Host '=== ONE LOGICAL CHANGE ==='
$oldControllers = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
    $_.CommandLine -and
    ($_.CommandLine -like '*queue-controller.ps1*' -or
     $_.CommandLine -like '*queue-controller-v2.ps1*' -or
     $_.CommandLine -like '*queue-controller-v3.ps1*') -and
    $_.ProcessId -ne $PID
})
foreach ($p in $oldControllers) {
    Stop-Process -Id $p.ProcessId -Force -ErrorAction SilentlyContinue
    Write-Host ('STOPPED_OLD_CONTROLLER_PID=' + $p.ProcessId)
}

$controllerText = @'
$ErrorActionPreference = 'Stop'
$root = 'C:/3EN-Agent'
$stateFile = "$root/3en-agent.state.json"
$log = "$root/queue-controller-v3.log"
$token = $env:THREEEN_GH_TOKEN
$api = 'https://api.github.com/repos/3en4all/3en-command-runner/contents'

function QLog([string]$m) {
    Add-Content -LiteralPath $log -Encoding UTF8 -Value ((Get-Date -Format 'yyyy-MM-dd HH:mm:ss') + ' ' + $m)
}

Set-Content -LiteralPath $log -Encoding UTF8 -Value '=== QUEUE CONTROLLER V3 031-040 ==='

if ([string]::IsNullOrWhiteSpace($token)) {
    QLog 'FATAL=TOKEN_MISSING'
    exit 51
}

$headers = @{
    Authorization = ('Bearer ' + $token)
    Accept = 'application/vnd.github+json'
    'X-GitHub-Api-Version' = '2022-11-28'
}

$ids = @(
    '2026-09-09-031',
    '2026-09-09-032',
    '2026-09-09-033',
    '2026-09-09-034',
    '2026-09-09-035',
    '2026-09-09-036',
    '2026-09-09-037',
    '2026-09-09-038',
    '2026-09-09-039',
    '2026-09-09-040'
)

$previous = '2026-09-09-043'

foreach ($id in $ids) {
    QLog ('WAIT_FOR=' + $previous)
    $deadline = (Get-Date).AddMinutes(90)
    $ready = $false

    while ((Get-Date) -lt $deadline) {
        try {
            $s = Get-Content -LiteralPath $stateFile -Raw | ConvertFrom-Json
            if ($s.lastExecutedId -eq $previous) {
                $ready = $true
                QLog ('TERMINAL=' + $previous + ' STATUS=' + $s.lastTerminalStatus)
                break
            }
        }
        catch {
            QLog ('STATE_RETRY=' + $_.Exception.Message)
        }
        Start-Sleep -Seconds 2
    }

    if (-not $ready) {
        QLog ('FATAL=TIMEOUT_WAITING_FOR_' + $previous)
        exit 52
    }

    try {
        $queued = Invoke-RestMethod -Method Get -Uri ($api + '/tasks/' + $id + '.json?ref=main') -Headers $headers
        $cleanB64 = [string]$queued.content
        $cleanB64 = $cleanB64.Replace("`n",'').Replace("`r",'')
        $taskBytes = [Convert]::FromBase64String($cleanB64)

        $current = Invoke-RestMethod -Method Get -Uri ($api + '/task.json?ref=main') -Headers $headers

        $bodyObject = @{
            message = ('Queue v3 promote ' + $id)
            content = [Convert]::ToBase64String($taskBytes)
            sha = $current.sha
            branch = 'main'
        }
        $body = $bodyObject | ConvertTo-Json -Compress

        Invoke-RestMethod -Method Put -Uri ($api + '/task.json') -Headers $headers -ContentType 'application/json' -Body $body | Out-Null
        QLog ('PROMOTED=' + $id)
    }
    catch {
        QLog ('FATAL=PROMOTE_FAILED ' + $id + ' ' + $_.Exception.Message)
        exit 53
    }

    $previous = $id
}

QLog 'ALL_10_TASKS_PROMOTED=TRUE'
exit 0

'@
Set-Content -LiteralPath $controller -Encoding UTF8 -Value $controllerText

$tokens = $null
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($controller,[ref]$tokens,[ref]$errors) | Out-Null
Write-Host ('QUEUE_V3_SYNTAX_ERRORS=' + @($errors).Count)
if (@($errors).Count -ne 0) {
    throw 'queue-controller-v3.ps1 syntax invalid.'
}

$proc = Start-Process -FilePath 'powershell.exe' -ArgumentList @(
    '-NoProfile','-ExecutionPolicy','Bypass','-File',$controller
) -PassThru

Write-Host ('QUEUE_V3_PID=' + $proc.Id)
Start-Sleep -Seconds 2

if ($proc.HasExited) {
    if (Test-Path -LiteralPath $newLog) {
        Get-Content -LiteralPath $newLog | ForEach-Object { Write-Host $_ }
    }
    throw ('queue-controller-v3 exited early code=' + $proc.ExitCode)
}

Write-Host 'QUEUE_V3_ARMED=TRUE'

test:
$ErrorActionPreference = 'Stop'
$controller = 'C:/3EN-Agent/queue-controller-v3.ps1'
if (-not (Test-Path -LiteralPath $controller)) { throw 'queue-controller-v3 missing' }
$tokens = $null
$errors = $null
[System.Management.Automation.Language.Parser]::ParseFile($controller,[ref]$tokens,[ref]$errors) | Out-Null
Write-Host ('QUEUE_V3_SYNTAX_ERRORS=' + @($errors).Count)
if (@($errors).Count -ne 0) { throw 'queue-controller-v3 syntax invalid' }
$p = @(Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object {
    $_.CommandLine -and $_.CommandLine -like '*queue-controller-v3.ps1*'
})
Write-Host ('QUEUE_V3_PROCESS_COUNT=' + $p.Count)
if ($p.Count -lt 1) { throw 'queue-controller-v3 not running' }
Write-Host 'CHAPTER_043_TEST=PASS'
Write-Host 'QUEUE_031_040_WILL_START_AFTER_043_FINALIZE=TRUE'

rollback:
$ErrorActionPreference = 'Continue'
$p = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
    $_.CommandLine -and $_.CommandLine -like '*queue-controller-v3.ps1*'
})
foreach ($x in $p) {
    if ($x.ProcessId -ne $PID) {
        Stop-Process -Id $x.ProcessId -Force -ErrorAction SilentlyContinue
    }
}
Write-Host 'QUEUE_V3_STOPPED_IF_PRESENT'
Write-Host 'Backup preserved under C:/3EN-Agent/backups/043.'
